insert into posts (id, author_id, kind, body, duel_id, community_id, tickers, created_at) values
  ('567984fd-17b5-5793-adbf-3152892516a7', '24fa1f4a-6d32-5705-ae2f-1a351f8df930', 'opinion', 'i think nvda will outperform msft this month. data center capex isn''t slowing down.', null, 'c5ca0604-43fd-5c14-a76b-95aac8aec0d5', array['NVDA','MSFT']::text[], '2026-11-25T18:06:00.000Z'),
  ('18d0297e-a2cd-5565-affc-7f3d60dcddf6', '4c77dc80-783f-5c29-a3fb-f998c5063c2d', 'duel', 'put $10 on meta vs googl with @leolongterm. reels > search. fight me.', '472eaa49-ef66-5e54-a63c-48ec707718f2', null, array[]::text[], '2026-11-25T17:18:00.000Z'),
  ('586e8f3d-3206-5c79-ad30-0086bdd324b9', 'd49b760d-dc9c-5ec4-a60b-710e31686f6e', 'opinion', 'aapl quietly outperforms tsla this week. nobody''s ready for the services numbers.', null, null, array['AAPL','TSLA']::text[], '2026-11-25T16:30:00.000Z'),
  ('6dd860d5-3151-5397-a7ad-80f59f9901a5', 'd49b760d-dc9c-5ec4-a60b-710e31686f6e', 'result', 'lost to @alexrivers. nvda +5% vs my aapl +3%. respect. rematch is already live.', '96c52f86-d503-5d62-aa12-9531584f7523', null, array[]::text[], '2026-11-25T15:30:00.000Z'),
  ('3976e450-26c5-551f-a148-b6d719ca8b64', '8e9910b2-7cb3-5eab-afa7-0108f492961a', 'text', 'amzn chart looks like a staircase. not financial advice, just geometry.', null, 'be2f2392-2e1e-5219-a074-dd7fd09910a1', array['AMZN']::text[], '2026-11-25T14:30:00.000Z'),
  ('31c96492-cba9-5a30-a728-9114ef5459a0', '22b35112-2c84-50c0-afc7-e43445ea4aef', 'duel', 'gme vs amc. me vs @zoe.memes. the meme civil war starts at the close.', '3889bb91-4bf0-5044-a57c-ee4679c0015b', null, array[]::text[], '2026-11-25T14:00:00.000Z'),
  ('9a038cf1-99ea-5126-abfe-103c489533d6', '77d9cc81-bb22-5a2e-ab3f-cb844df4b5a3', 'opinion', 'ko over dis this quarter. boring wins.', null, '510ef3ee-3f91-58c8-aa34-0d5c493464e6', array['KO','DIS']::text[], '2026-11-25T13:30:00.000Z'),
  ('d264fc55-d6e8-5826-a48a-dc75f614b969', '8e9910b2-7cb3-5eab-afa7-0108f492961a', 'result', 'msft +3.00% vs googl +3.00%. an actual dead heat with @leolongterm. stakes back.', '45623fb2-ce0f-544a-a4f6-c71fb95d0d4a', null, array[]::text[], '2026-11-25T12:30:00.000Z'),
  ('55dae956-fc43-5ddc-a549-a59de82d1511', '04c305f4-717e-59bd-a299-5507aeb028b4', 'opinion', 'tsm is the toll road. amd is a car on it. tsm beats amd this month.', null, 'ff92e003-a797-5b06-aaaf-393e07b392b1', array['TSM','AMD']::text[], '2026-11-25T11:30:00.000Z'),
  ('2e15a5f0-47e9-5497-a089-50346cadfdaf', '4c90e273-1dd0-5b23-a6a2-1ed4e746bd4d', 'text', 'reminder that beef compares percentage returns, not share prices. a $3 stock can absolutely beat a $900 one.', null, null, array[]::text[], '2026-11-25T10:30:00.000Z'),
  ('9aa5e6ec-b545-5067-adf7-b8e8f7265c81', 'a8eab8d8-f331-51cc-ac8f-baf18a27f92e', 'opinion', 'coin over pltr. already put $20 on it vs @alexrivers.', null, null, array['COIN','PLTR']::text[], '2026-11-25T09:30:00.000Z'),
  ('3cd1c404-b6a2-53a8-a4f4-29b6d2f63a9a', '4c77dc80-783f-5c29-a3fb-f998c5063c2d', 'result', 'both fell. meta fell less (−2% vs tsla −5%). still counts. thanks @samtrades 🙏', 'b2b699d1-27c7-5118-a2ca-7ba14dbf3c0a', null, array[]::text[], '2026-11-25T08:30:00.000Z'),
  ('de6f57c6-d8f7-5c39-a001-808842d2cef4', '448676e6-7051-55dd-a5a6-3d13111d321d', 'opinion', 'tsla over aapl by friday. @demo you in?', null, null, array['TSLA','AAPL']::text[], '2026-11-25T07:30:00.000Z'),
  ('293f7534-a139-550b-a602-93b5ddb71894', '970855ee-126c-59b9-a29f-2d19e5173fef', 'text', 'dca update: bought more msft, aapl, amzn. no beef today, just vibes.', null, null, array['MSFT','AAPL','AMZN']::text[], '2026-11-25T06:30:00.000Z'),
  ('7a395dc8-2e5c-5ba9-a7d2-8b8fa43ae5d3', 'c39e78c1-2708-5bdc-a3bf-30c37df40955', 'opinion', 'amc will outperform gme. i''ve said this every week for 3 years. one day.', null, '5e9a8050-9e5a-5b80-af63-d746d6758225', array['AMC','GME']::text[], '2026-11-25T05:30:00.000Z'),
  ('f78d8447-ded7-553d-a6cc-e4a530761b55', '04c305f4-717e-59bd-a299-5507aeb028b4', 'result', 'semis showdown is done. 4 of us, 4 chips. results inside.', '0f2d4520-a1e0-5612-ad2c-db8f478b76e0', null, array[]::text[], '2026-11-25T04:30:00.000Z'),
  ('f82720b8-8a9e-5de1-a087-a3a4b518ae79', '8e9910b2-7cb3-5eab-afa7-0108f492961a', 'opinion', 'amzn beats cost over the month. i''m on the other side of @mayabuys.', null, null, array['AMZN','COST']::text[], '2026-11-25T02:30:00.000Z'),
  ('e22435a2-ac9a-5428-ac0f-4931a3d214ef', '22b35112-2c84-50c0-afc7-e43445ea4aef', 'text', 'smci duel is paused bc of a trading halt in the data. no winner till prices are verified. respect the process i guess.', null, null, array['SMCI']::text[], '2026-11-25T00:30:00.000Z'),
  ('dca924fd-95d6-5198-aeda-e20ec6847317', '4c90e273-1dd0-5b23-a6a2-1ed4e746bd4d', 'opinion', 'jpm over coin over a month. banks are back.', null, '510ef3ee-3f91-58c8-aa34-0d5c493464e6', array['JPM','COIN']::text[], '2026-11-24T22:30:00.000Z'),
  ('074bcfe4-e58f-5ce6-a18e-5226fa9b602f', '24fa1f4a-6d32-5705-ae2f-1a351f8df930', 'opinion', 'pltr will cook coin. duel''s live, $20 each.', null, 'c5ca0604-43fd-5c14-a76b-95aac8aec0d5', array['PLTR','COIN']::text[], '2026-11-24T20:30:00.000Z'),
  ('4c065478-5e87-58c2-a19d-ed379e1a49b9', '77d9cc81-bb22-5a2e-ab3f-cb844df4b5a3', 'text', 'long-term community: what''s one stock you''d hold for 10 years without checking?', null, '510ef3ee-3f91-58c8-aa34-0d5c493464e6', array[]::text[], '2026-11-24T16:30:00.000Z'),
